changeSet.sql:
INSERT INTO sub_modules (name, code, module_id, enabled)
SELECT 'Caja', 'CASH', (SELECT id FROM modules WHERE code = 'GENERAL'), 1
WHERE NOT EXISTS (SELECT 1 FROM sub_modules WHERE code = 'CASH');

INSERT INTO base_permissions (name, code, sub_module_id, enabled)
SELECT 'Operar caja', 'cashregister.operate', (SELECT id FROM sub_modules WHERE code = 'CASH'), 1
WHERE NOT EXISTS (SELECT 1 FROM base_permissions WHERE code = 'cashregister.operate');

INSERT INTO base_permissions (name, code, sub_module_id, enabled)
SELECT 'Cerrar caja', 'cashregister.close', (SELECT id FROM sub_modules WHERE code = 'CASH'), 1
WHERE NOT EXISTS (SELECT 1 FROM base_permissions WHERE code = 'cashregister.close');

INSERT INTO base_permissions (name, code, sub_module_id, enabled)
SELECT 'Ver caja', 'cashregister.read', (SELECT id FROM sub_modules WHERE code = 'CASH'), 1
WHERE NOT EXISTS (SELECT 1 FROM base_permissions WHERE code = 'cashregister.read');
